  "executor" TEXT COLLATE "C" NOT NULL,
  "requested_at" TEXT COLLATE "C" NOT NULL,
  "evidence" TEXT COLLATE "C",
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment_set") REFERENCES fulfillment_set ("tenant", "id"),
  FOREIGN KEY ("tenant", "specification_pin") REFERENCES specification_pin ("tenant", "id"),
  FOREIGN KEY ("tenant", "executor") REFERENCES fulfillment_executor ("tenant", "id"),
  FOREIGN KEY ("tenant", "evidence") REFERENCES evidence_seal ("tenant", "id")
);

