  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "connection") REFERENCES connection ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE observation (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "desired" TEXT COLLATE "C" NOT NULL,
  "run" TEXT COLLATE "C" NOT NULL,
  "finish" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "observed_at" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "desired") REFERENCES desired_revision ("tenant", "id"),
  FOREIGN KEY ("tenant", "run") REFERENCES evaluation_run ("tenant", "id"),
  FOREIGN KEY ("tenant", "finish") REFERENCES evaluation_finish ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE drift (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "observation" TEXT COLLATE "C" NOT NULL,
  "desired" TEXT COLLATE "C" NOT NULL,
  "pin" TEXT COLLATE "C" NOT NULL,
  "anchor" TEXT COLLATE "C" NOT NULL,
  "field" TEXT COLLATE "C" NOT NULL,
  "explanation" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "observation") REFERENCES observation ("tenant", "id"),
  FOREIGN KEY ("tenant", "desired") REFERENCES desired_revision ("tenant", "id"),
  FOREIGN KEY ("tenant", "pin") REFERENCES specification_pin ("tenant", "id")
);

CREATE TABLE sync_conflict (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "mapping" TEXT COLLATE "C" NOT NULL,
  "connection" TEXT COLLATE "C" NOT NULL,
  "desired" TEXT COLLATE "C" NOT NULL,
  "drift" TEXT COLLATE "C" NOT NULL,
  "description" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "mapping") REFERENCES external_mapping ("tenant", "id"),
  FOREIGN KEY ("tenant", "connection") REFERENCES connection ("tenant", "id"),
  FOREIGN KEY ("tenant", "desired") REFERENCES desired_revision ("tenant", "id"),
  FOREIGN KEY ("tenant", "drift") REFERENCES drift ("tenant", "id")
);

CREATE TABLE sync_resolution (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "conflict" TEXT COLLATE "C" NOT NULL,
  "authority" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "conflict") REFERENCES sync_conflict ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE reconciliation_attempt (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "desired" TEXT COLLATE "C" NOT NULL,
  "observation" TEXT COLLATE "C" NOT NULL,
  "fulfillment" TEXT COLLATE "C" NOT NULL,
  "key_" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "desired") REFERENCES desired_revision ("tenant", "id"),
  FOREIGN KEY ("tenant", "observation") REFERENCES observation ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment") REFERENCES fulfillment ("tenant", "id")
);

CREATE TABLE reconciliation_result (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "attempt" TEXT COLLATE "C" NOT NULL,
  "desired" TEXT COLLATE "C" NOT NULL,
  "outcome" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "detail" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "attempt") REFERENCES reconciliation_attempt ("tenant", "id"),
  FOREIGN KEY ("tenant", "desired") REFERENCES desired_revision ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE reconciliation_event (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "scope" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "previous" TEXT COLLATE "C",
  "desired" TEXT COLLATE "C" NOT NULL,
  "desired_sequence" BIGINT NOT NULL,
  "kind" TEXT COLLATE "C" NOT NULL,
  "attempt" TEXT COLLATE "C",
  "result" TEXT COLLATE "C",
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "scope") REFERENCES reconciliation_scope ("tenant", "id"),
  FOREIGN KEY ("tenant", "previous") REFERENCES reconciliation_event ("tenant", "id"),
  FOREIGN KEY ("tenant", "desired") REFERENCES desired_revision ("tenant", "id"),
  FOREIGN KEY ("tenant", "attempt") REFERENCES reconciliation_attempt ("tenant", "id"),
  FOREIGN KEY ("tenant", "result") REFERENCES reconciliation_result ("tenant", "id")
);

CREATE TABLE accepted_record (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "run" TEXT COLLATE "C" NOT NULL,
  "mapping" TEXT COLLATE "C" NOT NULL,
  "connection" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "previous" TEXT COLLATE "C",
  "support" TEXT COLLATE "C" NOT NULL,
  "lineage" TEXT COLLATE "C" NOT NULL,
  "source_node" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "mapping") REFERENCES external_mapping ("tenant", "id"),
  FOREIGN KEY ("tenant", "connection") REFERENCES connection ("tenant", "id"),
  FOREIGN KEY ("tenant", "previous") REFERENCES accepted_record ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id"),
  FOREIGN KEY ("tenant", "lineage") REFERENCES lineage_relation ("tenant", "id"),
  FOREIGN KEY ("tenant", "source_node") REFERENCES lineage_node ("tenant", "id")
);

CREATE TABLE sync_cursor (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "connection" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "previous" TEXT COLLATE "C",
  "run" TEXT COLLATE "C" NOT NULL,
  "seal" TEXT COLLATE "C" NOT NULL,
  "token" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "connection") REFERENCES connection ("tenant", "id"),
  FOREIGN KEY ("tenant", "previous") REFERENCES sync_cursor ("tenant", "id")
);

CREATE TABLE sync_run (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "connection" TEXT COLLATE "C" NOT NULL,
  "key_" TEXT COLLATE "C" NOT NULL,
  "before" TEXT COLLATE "C",
  "after_token" TEXT COLLATE "C" NOT NULL,
  "expected_count" BIGINT NOT NULL,
  "fulfillment" TEXT COLLATE "C" NOT NULL,
  "desired" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "connection") REFERENCES connection ("tenant", "id"),
  FOREIGN KEY ("tenant", "before") REFERENCES sync_cursor ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment") REFERENCES fulfillment ("tenant", "id"),
  FOREIGN KEY ("tenant", "desired") REFERENCES desired_revision ("tenant", "id")
);

CREATE TABLE sync_seal (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "run" TEXT COLLATE "C" NOT NULL,
  "head" TEXT COLLATE "C" NOT NULL,
  "count" BIGINT NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "run") REFERENCES sync_run ("tenant", "id"),
  FOREIGN KEY ("tenant", "head") REFERENCES accepted_record ("tenant", "id")
);

